package com.scms.backend.scheduling;
import java.time.*; import java.util.*; import com.scms.backend.account.*; import com.scms.backend.audit.*; import com.scms.backend.auth.InvalidAuthenticatedAccountException; import com.scms.backend.reception.CenterVisitRepository; import org.springframework.stereotype.Service; import org.springframework.transaction.annotation.Transactional;
@Service class AttendanceService { final ClassSessionRepository sessions;final BookingRepository bookings;final AttendanceRepository attendance;final AuditEventRepository audits;final AccountRepository accounts;final CenterVisitRepository visits;final SessionLifecycleService lifecycle;final Clock clock;
 AttendanceService(ClassSessionRepository s,BookingRepository b,AttendanceRepository a,AuditEventRepository au,AccountRepository ac,CenterVisitRepository v,SessionLifecycleService l,Clock c){sessions=s;bookings=b;attendance=a;audits=au;accounts=ac;visits=v;lifecycle=l;clock=c;}
 @Transactional List<AttendanceResponse> list(UUID coach,UUID sid){Instant now=clock.instant();lifecycle.catchUp(now);ClassSession s=owned(coach,sid);if(now.isBefore(s.getStartTime()))throw AttendanceException.closed();return bookings.findBookedAttendanceMembers(sid).stream().map(m->attendance.findByBookingId(m.getBookingId()).map(a->AttendanceResponse.from(a,m)).orElseThrow()).toList();}
 @Transactional AttendanceResponse update(UUID coach,UUID sid,UUID aid,AttendanceUpdateRequest req){Instant now=clock.instant();lifecycle.catchUp(now);ClassSession s=owned(coach,sid);if(req==null||req.status()==null)throw AttendanceException.invalid();if(now.isBefore(s.getStartTime())||!now.isBefore(s.getEndTime().plusSeconds(1800)))throw AttendanceException.closed();Attendance a=attendance.findById(aid).orElseThrow(AttendanceException::missing);var members=bookings.findBookedAttendanceMembers(sid);var m=members.stream().filter(x->aid.equals(x.getAttendanceId())).findFirst().orElseThrow(AttendanceException::missing);UUID visit=null;if(req.status()==AttendanceStatus.PRESENT)visit=visits.findOverlappingVisitId(m.getMemberId(),s.getStartTime(),s.getEndTime(),now).orElseThrow(AttendanceException::visit);AttendanceStatus before=a.getStatus();a.mark(req.status(),visit,coach,now);attendance.save(a);audits.save(new AuditEvent(UUID.randomUUID(),coach,"ATTENDANCE_CHANGED","Attendance",aid,"Coach changed attendance",Map.of("status",before.name()),Map.of("status",req.status().name())));return AttendanceResponse.from(a,m);}
 private ClassSession owned(UUID coach,UUID sid){if(!accounts.existsByIdAndRoleAndStatus(coach,AccountRole.COACH,AccountStatus.ACTIVE))throw new InvalidAuthenticatedAccountException();return sessions.findByIdAndTeachingCoach_Id(sid,coach).orElseThrow(AttendanceException::missing);}}
